package com.abcvpn.service;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import java.time.*;import java.util.Optional;import org.junit.jupiter.api.Test;import com.abcvpn.entity.Subscription;import com.abcvpn.enumeration.SyncStatus;import com.abcvpn.repository.SubscriptionRepository;
class SubscriptionServiceTest {
 @Test void renewsExpiredFromNow(){SubscriptionRepository repository=mock(SubscriptionRepository.class);Instant now=Instant.parse("2026-01-01T00:00:00Z");Subscription old=new Subscription(1,2,now.minusSeconds(1),false,null,null,SyncStatus.SYNCED,0,null,null,now,now);when(repository.findByTelegramIdForUpdate(1)).thenReturn(Optional.of(old));Instant result=new SubscriptionService(repository,Clock.fixed(now,ZoneOffset.UTC)).extend(1,3,30);assertThat(result).isEqualTo(now.plus(30,java.time.temporal.ChronoUnit.DAYS));verify(repository).upsertAccess(1,3,result);}
 @Test void renewsActiveFromCurrentExpiry(){SubscriptionRepository repository=mock(SubscriptionRepository.class);Instant now=Instant.parse("2026-01-01T00:00:00Z"),expiry=now.plusSeconds(86400);Subscription old=new Subscription(1,2,expiry,false,null,null,SyncStatus.SYNCED,0,null,null,now,now);when(repository.findByTelegramIdForUpdate(1)).thenReturn(Optional.of(old));Instant result=new SubscriptionService(repository,Clock.fixed(now,ZoneOffset.UTC)).extend(1,3,30);assertThat(result).isEqualTo(expiry.plus(30,java.time.temporal.ChronoUnit.DAYS));}
 @Test void legacyUrlMustExistAndBelongToActiveSubscription(){SubscriptionRepository repository=mock(SubscriptionRepository.class);Instant now=Instant.parse("2026-01-01T00:00:00Z");String url="https://sub.abc-vpn.example.com/key";Subscription active=new Subscription(1,2,now.plusSeconds(60),false,"1",url,SyncStatus.SYNCED,0,null,null,now,now);when(repository.findBySubscriptionUrl(url)).thenReturn(Optional.of(active));assertThat(new SubscriptionService(repository,Clock.fixed(now,ZoneOffset.UTC)).requireLegacyConnectionUrl(url)).isEqualTo(url);}
}
